SELECT , s.attr_nbr as z_attr_nbr, s.attr_name as z_attr_name, v.attr_value_name as z_attr_value_name, v.attr_value as z_attr_value FROM bt_skill_attr_value_rel r LEFT JOIN bt_skill_attr_spec s on s.attr_id = r.z_attr_id and s.tenant_id = r.tenant_id LEFT JOIN bt_skill_attr_value v on v.attr_value_id = r.z_attr_value_id and v.tenant_id = r.tenant_id WHERE r.status_cd = '00A'
AND r.tenant_id = #{tenantId}
AND r.a_attr_value_id IN (#{id})
